package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.HashMap;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveOutputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CharsetNames;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class CpioArchiveOutputStream_CpioArchiveOutputStream_TriageGen0Test {

    private static final short FORMAT_NEW = CpioArchiveOutputStream.FORMAT_NEW;
    private static final short FORMAT_NEW_CRC = CpioArchiveOutputStream.FORMAT_NEW_CRC;
    private static final short FORMAT_OLD_ASCII = CpioArchiveOutputStream.FORMAT_OLD_ASCII;
    private static final short FORMAT_OLD_BINARY = CpioArchiveOutputStream.FORMAT_OLD_BINARY;
    private static final short INVALID_FORMAT = 999;

    @Test
    public void testConstructorWithValidFormats() throws IOException {
        OutputStream out = new ByteArrayOutputStream();

        // Test FORMAT_NEW
        CpioArchiveOutputStream cos1 = new CpioArchiveOutputStream(out, FORMAT_NEW, 1024, "UTF-8");
        Assert.assertNotNull(cos1);
        cos1.close();

        // Test FORMAT_NEW_CRC
        CpioArchiveOutputStream cos2 = new CpioArchiveOutputStream(out, FORMAT_NEW_CRC, 1024, "UTF-8");
        Assert.assertNotNull(cos2);
        cos2.close();

        // Test FORMAT_OLD_ASCII
        CpioArchiveOutputStream cos3 = new CpioArchiveOutputStream(out, FORMAT_OLD_ASCII, 1024, "UTF-8");
        Assert.assertNotNull(cos3);
        cos3.close();

        // Test FORMAT_OLD_BINARY
        CpioArchiveOutputStream cos4 = new CpioArchiveOutputStream(out, FORMAT_OLD_BINARY, 1024, "UTF-8");
        Assert.assertNotNull(cos4);
        cos4.close();
    }






}

